local rows, by_name = {}, {}
for line in string.gmatch(ROW_TEXT, "[^\r\n]+") do
  local name, text = string.match(line, "^([^=]+)=(.*)$")
  assert(type(name) == "string" and name ~= "", "invalid fixed prerequisite row")
  local parents = {}
  if text ~= "" then
    for parent in string.gmatch(text, "[^|]+") do parents[#parents + 1] = parent end
  end
  local row = {name = name, parents = parents}
  assert(by_name[name] == nil, "duplicate fixed prerequisite row")
  rows[#rows + 1], by_name[name] = row, row
end
assert(#rows == 196, "fixed prerequisite row count differs")

return {
  rows = rows,
  by_name = by_name,
  expected_worker_effects = {
    ["worker-robots-speed-1"] = .35,
    ["worker-robots-speed-2"] = .4,
    ["worker-robots-speed-3"] = .45,
    ["worker-robots-speed-4"] = .55,
